'use client';
import { useEffect, useRef, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import '../designme.css';
import './action-cards.css';

/** What a card's picture shows: the teams whose commits come in, the deals whose close dates move, or the accounts whose drafts go out */
export type ActionCardPicture =
  | { kind: 'commit'; teams: string[] }
  | { kind: 'dates'; moves: { name: string; was: string; to: string }[] }
  | { kind: 'follow'; accounts: string[] };

export interface ActionCard {
  id: string;
  /** Like "Submit the Q4 commit" */
  title: string;
  /** The muted line under it, like "5 reps to go, due Friday." */
  detail: string;
  /** The button's label, like "Review commit" */
  action: string;
  onAction?: () => void;
  picture: ActionCardPicture;
}

export interface ActionCardsProps {
  /** The cards, three across from 900px wide. Defaults to the Sales CRM forecast's three */
  cards?: ActionCard[];
  className?: string;
}

export const ACTION_CARDS: ActionCard[] = [
  { id: 'commit', title: 'Submit the Q4 commit', detail: '5 reps to go, due Friday.', action: 'Review commit', picture: { kind: 'commit', teams: ['Key accounts', 'Growth', 'New business'] } },
  { id: 'dates', title: 'Move 4 close dates', detail: 'New dates are ready to be approved.', action: 'Review dates', picture: { kind: 'dates', moves: [
    { name: 'Renewal', was: 'Nov 25', to: 'Dec 9' }, { name: 'Renewal', was: 'Nov 23', to: 'Dec 11' }, { name: 'Studio seats', was: 'Nov 20', to: 'Dec 15' }, { name: 'Pilot', was: 'Nov 17', to: 'Dec 17' }] } },
  { id: 'follow', title: 'Send 4 follow-ups', detail: 'Drafts are ready to send. Review them.', action: 'Review drafts', picture: { kind: 'follow', accounts: ['Saltmarsh Foods', 'Moss & Ember', 'Marrow & Finch', 'Arbor & Vine'] } }
];

// each picture's pace, by its place in the row: how long an item stays, how long the list takes to move on, how late it starts
const PACE = [{ step: 3600, mv: 700, at: 0 }, { step: 3000, mv: 600, at: 700 }, { step: 4200, mv: 800, at: 1400 }];
const Tick = () => <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5" /></svg>;

/** The picture's items, each one a window when it's in focus */
function items(p: ActionCardPicture): ReactNode[] {
  if (p.kind === 'commit') return p.teams.map((t, i) => (
    <><span className="dm-axc-t">{t}</span>{[0, 1].map(r => <span key={r} className="dm-axc-r"><span className="dm-axc-l" style={{ width: [[60, 44], [52, 38], [56, 46]][i % 3][r] + '%' }} /><span className={cx('dm-axc-m', !r && 'dm-in')} data-go={r ? '' : undefined}><Tick /></span></span>)}</>));
  if (p.kind === 'dates') return p.moves.map(m => (
    <><span className="dm-axc-r"><span className="dm-axc-i" style={{ ['--dm-a' as string]: 'var(--dm-av-r)', ['--dm-ai' as string]: 'var(--dm-av-r-ink)' }}><Icon name="cal" size="xs" /></span><span className="dm-axc-n">{m.name}</span></span>
      <span className="dm-axc-d"><s className="dm-num">{m.was}</s><Icon name="right" size="xs" /><span className="dm-tag dm-axc-g dm-num" data-go="">{m.to}</span></span><span className="dm-axc-l" style={{ width: '72%' }} /></>));
  return p.accounts.map((a, i) => (
    <><span className="dm-axc-r"><span className="dm-axc-i" style={{ ['--dm-a' as string]: 'var(--dm-av-b)', ['--dm-ai' as string]: 'var(--dm-av-b-ink)' }}><Icon name="mail" size="xs" /></span><span className="dm-axc-n">{a}</span></span>
      <span className="dm-axc-l" style={{ width: [88, 76, 82, 70][i % 4] + '%' }} /><span className="dm-axc-r"><span className="dm-tag dm-axc-g dm-dr" data-go=""><Icon name="spark" size="xs" /><span className="dm-sw"><span className="dm-a">Drafted</span><span className="dm-b">Sent</span></span></span></span></>));
}

function Card({ card, pace, held }: { card: ActionCard; pace: (typeof PACE)[number]; held: { current: boolean } }) {
  const vis = useRef<HTMLDivElement>(null), track = useRef<HTMLDivElement>(null), cur = useRef<SVGSVGElement>(null);
  const reduce = useReducedMotion();
  const list = items(card.picture), n = list.length;
  // the track: the last item first (the slip above), the list, then its first two again so the loop can wrap unseen
  const seq = n ? [list[n - 1], ...list, list[0], list[1 % n]] : [];
  useEffect(() => {
    const v = vis.current, k = track.current, c = cur.current; if (!v || !k || !c || !n) return;
    const W = [...k.children] as HTMLElement[];
    let i = 1, alive = true;
    const timers: ReturnType<typeof setTimeout>[] = [];
    const place = (idx: number, anim: boolean) => { k.classList.toggle('dm-mv', anim); const it = W[idx]; k.style.transform = `translateY(${Math.round((v.clientHeight - it.offsetHeight) / 2 - it.offsetTop)}px)`;
      W.forEach((x, m) => x.classList.toggle('dm-on', m === idx)); };
    place(i, false);
    const ro = new ResizeObserver(() => place(i, false)); ro.observe(v);
    // a wait that only counts while no mouse rests on the cards
    const wait = (ms: number) => new Promise<void>(res => { let left = ms, last = performance.now();
      const t = () => { if (!alive) return; const now = performance.now(); if (!held.current) left -= now - last; last = now; if (left <= 0) res(); else timers.push(setTimeout(t, 50)); };
      timers.push(setTimeout(t, 50)); });
    const at = (el: Element) => { const a = v.getBoundingClientRect(), b = el.getBoundingClientRect(); return [b.left - a.left + b.width * .55, b.top - a.top + b.height * .5]; };
    const run = async () => {
      await wait(pace.at + 900);
      while (alive) {
        const go = W[i].querySelector('[data-go]');
        if (go) {
          const [x, y] = at(go);
          c.classList.remove('dm-press'); c.style.transition = 'none'; c.style.transform = `translate(${x + 34}px,${y + 26}px)`; void c.getBoundingClientRect(); c.style.transition = '';
          c.style.opacity = '1'; c.style.transform = `translate(${x}px,${y}px)`;
          await wait(700); if (!alive) return;
          c.classList.add('dm-press'); c.style.transform = `translate(${x}px,${y}px) scale(.8)`;
          await wait(140); if (!alive) return;
          c.style.transform = `translate(${x}px,${y}px)`; go.classList.add(go.classList.contains('dm-axc-m') ? 'dm-in' : 'dm-ok');
          await wait(520); if (!alive) return;
          c.classList.remove('dm-press'); c.style.opacity = '0'; c.style.transform = `translate(${x + 18}px,${y + 14}px)`;
        }
        await wait(Math.max(300, pace.step - 1700)); if (!alive) return;
        // scroll up to the next item; past the end, jump back unseen to the same item at the start, all fresh again
        i++; place(i, true);
        await wait(pace.mv + 60); if (!alive) return;
        if (i === n + 1) { i = 1; W.forEach(x => x.querySelectorAll('[data-go]').forEach(g => g.classList.remove('dm-in', 'dm-ok'))); place(i, false); }
      }
    };
    if (!reduce) run();
    return () => { alive = false; timers.forEach(clearTimeout); ro.disconnect(); };
  }, [n, reduce, pace, held]);
  return (
    <div className="dm-panel dm-axc-c" data-ax={card.id}>
      <div className="dm-axc-tx"><b>{card.title}</b><p>{card.detail}</p><button type="button" className="dm-pill dm-line dm-sm" onClick={card.onAction}>{card.action}</button></div>
      <div ref={vis} className="dm-axc-v" aria-hidden="true">
        <div ref={track} className="dm-axc-k" style={{ ['--dm-ax-mv' as string]: pace.mv + 'ms' }}>{seq.map((x, j) => <div key={j} className="dm-axc-w">{x}</div>)}</div>
        <svg ref={cur} className="dm-axc-cur" viewBox="0 0 20 20" aria-hidden="true"><path d="M4 2.5l12 6.2-5.3 1.5-2.4 5.1z" /></svg>
      </div>
    </div>
  );
}

/** What is waiting on a person, as a row of cards, each with its button and a small looping picture of what it opens, from
    the Sales CRM template's forecast. A mouse resting on the cards holds the pictures; with reduced motion they stay still */
export function ActionCards({ cards = ACTION_CARDS, className }: ActionCardsProps) {
  const held = useRef(false);
  return (
    <div className={cx('dm-axc', className)} data-dm="" onPointerEnter={e => { if (e.pointerType === 'mouse') held.current = true; }} onPointerLeave={() => { held.current = false; }}>
      <div className="dm-axc-row">{cards.map((c, i) => <Card key={c.id} card={c} pace={PACE[i % PACE.length]} held={held} />)}</div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Action cards ---------- */
/* the Sales CRM forecast's next steps (owner, 27 Nov; designed 16 Nov): each card says what is waiting, with a button that opens
   it, beside a small picture of what that button leads to. The picture is a short list: the item in focus is a window, its
   neighbours grey slips above and below. In a loop a pointer glides to the item, presses, the item changes (a commit ticks
   in, a new date is approved, a draft is sent), then the list scrolls up to the next. The three run at different speeds so
   they never move together, a resting pointer holds them, and with reduced motion they stay still. Three across; one under
   another below 900px */
.dm-card.dm-wide .dm-stage-in:has(>.dm-axc){max-width:none}
/* installed, its card takes the room it is given, so the row can be three across */
[data-dm]:has(>.dm-stage-in>.dm-axc),[data-dm]>.dm-stage-in:has(>.dm-axc){width:100%;max-width:none}
.dm-axc{--dm-axc-hair:color-mix(in srgb,color-mix(in srgb,var(--dm-line),var(--dm-fg) 9%) 50%,transparent);width:100%;container:axc/inline-size}
.dm-axc-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--dm-s-3)}
.dm-axc-c.dm-panel{overflow:hidden;display:grid;grid-template-columns:minmax(0,1fr) 50%;min-height:156px;border-radius:var(--dm-r-card);box-shadow:inset 0 0 0 1px var(--dm-axc-hair)}
.dm-axc-tx{position:relative;z-index:1;display:flex;flex-direction:column;align-items:flex-start;gap:6px;padding:var(--dm-s-4)}
.dm-axc-tx b{font-size:14px;font-weight:500;color:var(--dm-fg);line-height:1.35}
.dm-axc-tx p{margin:0 0 var(--dm-s-4);font-size:13px;line-height:1.45;color:var(--dm-muted)}
.dm-axc-tx .dm-pill{margin-top:auto}
.dm-axc-v{position:relative;min-width:0;overflow:hidden}
.dm-axc-k{position:absolute;left:10px;right:var(--dm-s-4);top:0;display:flex;flex-direction:column;gap:15px;will-change:transform}
.dm-axc-k.dm-mv{transition:transform var(--dm-ax-mv,.7s) cubic-bezier(.65,0,.35,1)}
/* an item: a window when it's in focus, a grey slip when it's not (its content hidden). The windows end 16px in from the
   card's right edge, on its content column (the template's 10px there is a near miss) */
.dm-axc-w{display:flex;flex-direction:column;gap:8px;padding:10px 12px;flex:none;border-radius:calc(var(--dm-r-card) - 10px);background:color-mix(in srgb,var(--dm-fg) 4%,var(--dm-surface));box-shadow:0 0 0 1px var(--dm-axc-hair);transition:background-color .45s var(--dm-ease),box-shadow .45s var(--dm-ease)}
.dm-axc-w>*{opacity:0;transition:opacity .35s var(--dm-ease)}
/* the window in focus takes Soft's card shadow */
.dm-axc-w.dm-on{background:var(--dm-surface);box-shadow:0 0 0 1px var(--dm-axc-hair),0 1px 1px rgba(0,0,0,.02),0 2px 4px -2px rgba(0,0,0,.025),0 6px 12px -6px rgba(0,0,0,.03),0 12px 24px -12px rgba(0,0,0,.035)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dm-axc-w.dm-on{box-shadow:0 0 0 1px var(--dm-axc-hair),0 1px 2px rgba(0,0,0,.22),0 4px 10px -4px rgba(0,0,0,.24),0 12px 24px -12px rgba(0,0,0,.28)}}
:root[data-theme="dark"] .dm-axc-w.dm-on{box-shadow:0 0 0 1px var(--dm-axc-hair),0 1px 2px rgba(0,0,0,.22),0 4px 10px -4px rgba(0,0,0,.24),0 12px 24px -12px rgba(0,0,0,.28)}
.dm-axc-w.dm-on>*{opacity:1}
/* the grey slips above and below the window are 30% fainter than the window (owner, 27 Nov); the window in focus is whole */
.dm-axc-w:not(.dm-on){opacity:.7}
.dm-axc-w{transition-property:background-color,box-shadow,opacity}
.dm-axc-t{font-size:12px;font-weight:500;color:var(--dm-fg);line-height:15px}
.dm-axc-r{display:flex;align-items:center;gap:8px;min-width:0;min-height:18px}
.dm-axc-l{display:block;height:6px;flex:none;border-radius:3px;background:var(--dm-chip)}
/* a rep's commit: a ring until it's in, then a grey disc with a tick (grey, not green) */
.dm-axc-m{position:relative;margin-left:auto;width:14px;height:14px;flex:none;display:grid;place-items:center;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--dm-faint);color:var(--dm-surface);transition:background-color .25s var(--dm-ease),box-shadow .25s var(--dm-ease)}
.dm-axc-m svg{width:9px;height:9px;fill:none;stroke:currentColor;stroke-width:3.6;stroke-linecap:round;stroke-linejoin:round;opacity:0;transform:scale(.5);transition:opacity .25s var(--dm-ease),transform .3s var(--dm-ease)}
.dm-axc-m.dm-in{background:var(--dm-faint);box-shadow:none}
.dm-axc-m.dm-in svg{opacity:1;transform:none}
.dm-axc-i{width:22px;height:22px;flex:none;display:grid;place-items:center;border-radius:calc(6px * var(--dm-rk));background:var(--dm-a);color:var(--dm-ai)}
.dm-axc-n{font-size:12px;font-weight:500;color:var(--dm-fg);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.dm-axc-d{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--dm-muted);white-space:nowrap}
.dm-axc-d s{text-decoration-color:currentColor}
/* a new date is grey until approved, then green; a draft is the accent tint until sent, then green */
.dm-axc .dm-tag.dm-axc-g{height:20px;font-size:11px;gap:4px;transition:background-color .25s var(--dm-ease),color .25s var(--dm-ease)}
.dm-axc .dm-tag.dm-axc-g.dm-ok{background:var(--dm-ok-bg);color:var(--dm-ok)}
.dm-axc .dm-tag.dm-axc-g.dm-dr{background:color-mix(in srgb,var(--dm-accent) 10%,transparent);color:var(--dm-accent-fg,var(--dm-accent))}
.dm-axc .dm-tag.dm-axc-g.dm-dr.dm-ok{background:var(--dm-ok-bg);color:var(--dm-ok)}
.dm-axc-g svg{width:10px;height:10px}
.dm-axc-g .dm-sw{display:inline-grid}
.dm-axc-g .dm-sw>*{grid-area:1/1;transition:opacity .25s var(--dm-ease),transform .3s var(--dm-ease)}
.dm-axc-g .dm-sw>.dm-b{opacity:0;transform:translateY(5px)}
.dm-axc-g.dm-ok .dm-sw>.dm-a{opacity:0;transform:translateY(-5px)}
.dm-axc-g.dm-ok .dm-sw>.dm-b{opacity:1;transform:none}
/* the pointer: glides to the thing, presses, glides off */
.dm-axc-cur{position:absolute;z-index:3;left:0;top:0;width:18px;height:18px;fill:var(--dm-accent-mark,var(--dm-accent));stroke:var(--dm-surface);stroke-width:1.5;stroke-linejoin:round;opacity:0;pointer-events:none;transition:transform .65s cubic-bezier(.22,1,.36,1),opacity .3s var(--dm-ease)}
.dm-axc-cur.dm-press{transition:transform .14s var(--dm-ease),opacity .3s var(--dm-ease)}
/* Blueprint: square, a hairline, no shadow; the draft tag in the lime tint */
:root:not([data-style="soft"],[data-style="clean"]) .dm-axc-c.dm-panel:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)),:root:not([data-style="soft"],[data-style="clean"]) :is(.dm-axc-w,.dm-axc-i):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:0}
:root:not([data-style="soft"],[data-style="clean"]) .dm-axc-w.dm-on:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-fg) 18%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) .dm-axc .dm-tag.dm-axc-g.dm-dr:not(.dm-ok):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:color-mix(in srgb,var(--dm-accent) 40%,transparent)}
@media (prefers-color-scheme:dark){:root:not([data-style="soft"],[data-style="clean"]):not([data-theme="light"]) .dm-axc .dm-tag.dm-axc-g.dm-dr:not(.dm-ok):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:color-mix(in srgb,var(--dm-accent) 14%,transparent)}}
:root:not([data-style="soft"],[data-style="clean"])[data-theme="dark"] .dm-axc .dm-tag.dm-axc-g.dm-dr:not(.dm-ok):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:color-mix(in srgb,var(--dm-accent) 14%,transparent)}
@media (prefers-reduced-motion:reduce){.dm-axc-k.dm-mv,.dm-axc-w,.dm-axc-w>*,.dm-axc-cur,.dm-axc-m,.dm-axc-m svg{transition:none}}
/* one under another on a narrow stage, the picture beside the words */
@container axc (max-width:899px){.dm-axc-row{grid-template-columns:minmax(0,1fr)}.dm-axc-c.dm-panel{grid-template-columns:minmax(0,1fr) minmax(200px,40%)}}
@container axc (max-width:479px){.dm-axc-c.dm-panel{grid-template-columns:minmax(0,1fr) 46%;min-height:168px}.dm-axc-k{left:8px}}
